// configJSONError returns a ParseError for the JSON token v at path.
func configJSONError(path string, v jsontext.Token, err error) error {
	return &configulator.ParseError{
		Err:   err,
		Path:  path,
		Value: v.String(),
	}
}

// PrintConfig renders every field as "path = value" lines, redacting
// fields tagged secret:"true". The origin Report holds no values,
// so this is the only place redaction happens.
func (c Config) PrintConfig() string {
	var b strings.Builder
	fmt.Fprintf(&b, "log-level = %v\n", c.LogLevel)
	fmt.Fprintf(&b, "ping-interval = %v\n", c.PingInterval)
	fmt.Fprintf(&b, "hub.url = %v\n", c.Hub.URL)
	b.WriteString("hub.token = (redacted)\n")
	fmt.Fprintf(&b, "hub.token-file = %v\n", c.Hub.TokenFile)
	fmt.Fprintf(&b, "store.keyring = %v\n", c.Store.Keyring)
	fmt.Fprintf(&b, "store.token-file = %v\n", c.Store.TokenFile)
	fmt.Fprintf(&b, "store.state-dir = %v\n", c.Store.StateDir)
	fmt.Fprintf(&b, "device.roots = %v\n", c.Device.Roots)
	fmt.Fprintf(&b, "device.tmp-dir = %v\n", c.Device.TempDir)
	fmt.Fprintf(&b, "device.shell = %v\n", c.Device.Shell)
	fmt.Fprintf(&b, "device.wsl-distro = %v\n", c.Device.WSLDistro)
	fmt.Fprintf(&b, "device.resume-buffer = %v\n", c.Device.ResumeBuffer)
	fmt.Fprintf(&b, "device.max-grace = %v\n", c.Device.MaxGrace)
	fmt.Fprintf(&b, "device.command-memory-max = %v\n", c.Device.CommandMemoryMax)
	fmt.Fprintf(&b, "gateway.listen = %v\n", c.Gateway.Listen)
	fmt.Fprintf(&b, "gateway.splice = %v\n", c.Gateway.Splice)
	fmt.Fprintf(&b, "chat.managed = %v\n", c.Chat.Managed)
	fmt.Fprintf(&b, "chat.managed-dir = %v\n", c.Chat.ManagedDir)
	fmt.Fprintf(&b, "chat.hermes = %v\n", c.Chat.Hermes)
	fmt.Fprintf(&b, "acp-host.listen = %v\n", c.ACPHost.Listen)
	fmt.Fprintf(&b, "acp-host.backend-id = %v\n", c.ACPHost.BackendID)
	fmt.Fprintf(&b, "acp-host.hub-public-key = %v\n", c.ACPHost.HubPublicKey)
	fmt.Fprintf(&b, "acp-host.hub-public-key-file = %v\n", c.ACPHost.HubPublicKeyFile)
	fmt.Fprintf(&b, "acp-host.hermes = %v\n", c.ACPHost.Hermes)
	fmt.Fprintf(&b, "acp-host.placeholder = %v\n", c.ACPHost.Placeholder)
	fmt.Fprintf(&b, "acp-host.max-processes = %v\n", c.ACPHost.MaxProcesses)
	fmt.Fprintf(&b, "acp-host.bindings-file = %v\n", c.ACPHost.BindingsFile)
	fmt.Fprintf(&b, "acp-host.gateway-health-url = %v\n", c.ACPHost.GatewayHealthURL)
	fmt.Fprintf(&b, "reconnect.min-backoff = %v\n", c.Reconnect.MinBackoff)
	fmt.Fprintf(&b, "reconnect.max-backoff = %v\n", c.Reconnect.MaxBackoff)
	fmt.Fprintf(&b, "browser.enabled = %v\n", c.Browser.Enabled)
	fmt.Fprintf(&b, "browser.allow-hosts = %v\n", c.Browser.AllowHosts)
	fmt.Fprintf(&b, "browser.confirm-hosts = %v\n", c.Browser.ConfirmHosts)
	fmt.Fprintf(&b, "browser.autologin-hosts = %v\n", c.Browser.AutologinHosts)
	fmt.Fprintf(&b, "browser.start-firefox = %v\n", c.Browser.StartFirefox)
	fmt.Fprintf(&b, "browser.firefox-command = %v\n", c.Browser.FirefoxCommand)
	b.WriteString("mcp.servers = (redacted)\n")
	fmt.Fprintf(&b, "mcp.idle-timeout = %v\n", c.MCP.IdleTimeout)
	fmt.Fprintf(&b, "update.auto = %v\n", c.Update.Auto)
	fmt.Fprintf(&b, "update.interval = %v\n", c.Update.Interval)
	if c.Usage.Enabled == nil {
		b.WriteString("usage.enabled = <unset>\n")
	} else {
		fmt.Fprintf(&b, "usage.enabled = %v\n", *c.Usage.Enabled)
	}
	fmt.Fprintf(&b, "usage.claude-dirs = %v\n", c.Usage.ClaudeDirs)
	fmt.Fprintf(&b, "usage.hermes-accounts-dir = %v\n", c.Usage.HermesAccountsDir)
	fmt.Fprintf(&b, "usage.state-file = %v\n", c.Usage.StateFile)
	return b.String()
}

func configQuoteKey(k string) string {
	if strings.ContainsAny(k, ".[") {
		return "\"" + strings.NewReplacer("\\", "\\\\", "\"", "\\\"").Replace(k) + "\""
	}
	return k
}
